<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {Activity,Play,Plus,RadioTower,RefreshCw,Server,Wifi} from 'lucide-vue-next';import {useAuthStore} from '@/stores/useAuthStore';import {agentStatusLabel,taskProgress} from '@/features/discovery/discoveryModel'
type Agent={id:string;name:string;hostname:string;ip:string;status:string;version:string;lastHeartbeat:string};type Item={id:string;name:string;ip:string;state:string};type Task={id:string;name:string;scope:string;status:string;discovered:number;imported:number;items?:Item[]};type Summary={total:number;online:number;tasks:number;pending:number}
const auth=useAuthStore(),agents=ref<Agent[]>([]),tasks=ref<Task[]>([]),summary=ref<Summary>(),busy=ref(false),error=ref('');const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function request<T>(url:string,options?:RequestInit){const r=await fetch(url,{...options,headers:headers.value});if(!r.ok)throw new Error(`请求失败 (${r.status})`);return r.json() as Promise<T>};async function load(){busy.value=true;error.value='';try{[summary.value,agents.value,tasks.value]=await Promise.all([request<Summary>('/api/v1/discovery/summary'),request<Agent[]>('/api/v1/discovery/agents'),request<Task[]>('/api/v1/discovery/tasks')])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}};async function createTask(){await request<Task>('/api/v1/discovery/tasks',{method:'POST',body:JSON.stringify({name:`网段扫描 ${tasks.value.length+1}`,source:'network',scope:'10.20.0.0/24'})});await load()};async function action(task:Task,type:'run'|'reconcile'){await request<Task>(`/api/v1/discovery/tasks/${task.id}/${type}`,{method:'POST'});await load()};onMounted(load)
</script>
<template><section class="discovery-page"><header class="discovery-heading"><div><span>AGENT & AUTO DISCOVERY</span><h1>Agent 与自动发现</h1><p>统一管理采集端在线状态、发现任务与 CMDB 数据入库。</p></div><button class="primary" @click="createTask"><Plus/>新建发现任务</button></header><div v-if="error" class="discovery-error">{{error}}</div><div class="discovery-summary"><article><RadioTower/><div><span>Agent 总数</span><strong>{{summary?.total??0}}</strong></div></article><article><Wifi/><div><span>在线 Agent</span><strong>{{summary?.online??0}}</strong></div></article><article><Activity/><div><span>待纳管资产</span><strong>{{summary?.pending??0}}</strong></div></article><article><Server/><div><span>发现任务</span><strong>{{summary?.tasks??0}}</strong></div></article></div><div class="discovery-grid"><section class="discovery-panel"><header><div><h2>采集端状态</h2><span>实时心跳与版本</span></div><button @click="load"><RefreshCw :class="{spin:busy}"/></button></header><div class="agent-list"><article v-for="agent in agents" :key="agent.id"><i :data-status="agent.status"></i><div><strong>{{agent.name}}</strong><span>{{agent.ip}} · {{agent.hostname}} · v{{agent.version}}</span></div><b :data-status="agent.status">{{agentStatusLabel(agent.status)}}</b><time>{{agent.lastHeartbeat||'尚未连接'}}</time></article></div></section><section class="discovery-panel tasks"><header><div><h2>发现任务</h2><span>扫描、识别并纳管基础设施</span></div></header><article v-for="task in tasks" :key="task.id" class="task-card"><div class="task-title"><div><strong>{{task.name}}</strong><span>{{task.scope}}</span></div><b>{{task.status}}</b></div><div class="task-counts"><span>已发现 <strong>{{task.discovered}}</strong></span><span>已入库 <strong>{{task.imported}}</strong></span><span>纳管率 <strong>{{taskProgress(task)}}%</strong></span></div><div class="task-progress"><i :style="{width:taskProgress(task)+'%'}"></i></div><div v-if="task.items?.length" class="discovered-items"><span v-for="item in task.items" :key="item.id"><Server/>{{item.name}}<small>{{item.ip}}</small><b>{{item.state==='imported'?'已入库':'待入库'}}</b></span></div><footer><button v-if="task.status!=='completed'" @click="action(task,'run')"><Play/>执行扫描</button><button class="primary" :disabled="!task.discovered||task.imported===task.discovered" @click="action(task,'reconcile')">同步至 CMDB</button></footer></article></section></div></section></template>
